/* Registered collectible-card-artwork / media-frames exceptions.
   Fixed print materials belong to the card; application controls follow the theme. */
.ds-agent-card-face {
  --ds-card-edge: var(--ds-card-gold-edge, #a48045);
  --ds-card-frame: var(--ds-card-gold-frame, #b79b68);
  --ds-card-paper: var(--ds-card-gold-paper, #faf3e6);
  --ds-card-ink: var(--ds-card-gold-ink, #513e27);
  position: relative;
  container-type: inline-size;
  width: 100%;
  height: 100%;
  min-height: 0;
  aspect-ratio: 244 / 352;
  isolation: isolate;
  border: var(--ds-border-strong, 2px) solid var(--ds-card-edge);
  border-radius: var(--ds-radius-field, 0.75rem);
  background: var(--ds-card-art-ground, #22262e);
  color: var(--ds-card-art-text, #ffffff);
  overflow: visible;
}
.ds-agent-card-face--silver {
  --ds-card-edge: var(--ds-card-silver-edge, #788591);
  --ds-card-frame: var(--ds-card-silver-frame, #b8c4ce);
  --ds-card-paper: var(--ds-card-silver-paper, #f0f4f7);
  --ds-card-ink: var(--ds-card-silver-ink, #35444f);
}
.ds-agent-card-face--ink {
  --ds-card-edge: var(--ds-card-ink-edge, #48505b);
  --ds-card-frame: var(--ds-card-ink-frame, #89929d);
  --ds-card-paper: var(--ds-card-ink-paper, #e9ebef);
  --ds-card-ink: var(--ds-card-ink-ink, #353d48);
}
.ds-agent-card-face--context,
.ds-agent-card-face--memory {
  --ds-card-edge: var(--ds-card-jade-edge, #447e70);
  --ds-card-frame: var(--ds-card-jade-frame, #91b8a9);
  --ds-card-paper: var(--ds-card-jade-paper, #edf5ed);
  --ds-card-ink: var(--ds-card-jade-ink, #2b4f42);
}
.ds-agent-card-face--automation {
  --ds-card-edge: var(--ds-card-violet-edge, #85659e);
  --ds-card-frame: var(--ds-card-violet-frame, #b09bbf);
  --ds-card-paper: var(--ds-card-violet-paper, #f4eef7);
  --ds-card-ink: var(--ds-card-violet-ink, #594667);
}
.ds-agent-card-face::after {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px solid var(--ds-card-frame);
  border-radius: var(--ds-radius-compact-control, 0.5rem);
  pointer-events: none;
}
.ds-agent-card-art {
  position: absolute;
  inset: 6px;
  z-index: -1;
  border-radius: var(--ds-radius-compact-control, 0.5rem);
  overflow: hidden;
  background: var(--ds-card-art-ground, #22262e);
}
.ds-agent-card-art::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--ds-card-art-shade, #08111e) 88%, transparent),
    color-mix(in srgb, var(--ds-card-art-shade, #08111e) 20%, transparent) 30%,
    transparent 48%
  );
}
.ds-agent-card-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
}
.ds-agent-card-face--full .ds-agent-card-art--square img {
  height: 74%;
}
.ds-agent-card-heading {
  display: flex;
  align-items: center;
  gap: var(--ds-space-control-gap, 0.5rem);
  padding: 6% 6% 0;
}
.ds-agent-card-heading .ds-agent-card-title {
  flex: 1;
  margin: 0;
  font-weight: 700;
  font-family: var(--ds-card-art-font, "Songti SC", "STSong", "Noto Serif CJK SC", serif);
  font-size: clamp(20px, 8.2cqw, 28px);
  line-height: 1.3;
  text-shadow: 0 1px 3px var(--ds-card-art-shade, #08111e);
}
.ds-agent-card-seal {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(var(--ds-space-control-gap, 0.5rem) / 2);
  border: 1px solid var(--ds-card-frame);
  border-radius: var(--ds-radius-icon-action, 9999px);
}
.ds-agent-card-category {
  display: block;
  margin: 2% 6%;
  color: var(--ds-card-art-text, #ffffff);
}
.ds-agent-card-rules {
  position: absolute;
  left: 4%;
  right: 4%;
  bottom: 3%;
  min-height: 31%;
  padding: 4%;
  background: var(--ds-card-paper);
  color: var(--ds-card-ink);
  border: 1px solid var(--ds-card-frame);
  border-radius: 2px;
}
.ds-agent-card-summary {
  font-size: clamp(11px, 4.2cqw, 14px);
  line-height: 1.7;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  min-height: 2.8em;
  margin-top: calc(var(--ds-space-control-gap, 0.5rem) / 2);
  overflow-wrap: anywhere;
}
.ds-agent-card-stats {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ds-space-control-gap, 0.5rem);
  margin-top: var(--ds-space-control-gap, 0.5rem);
  padding-top: calc(var(--ds-space-control-gap, 0.5rem) * 0.75);
  border-top: 1px solid var(--ds-card-frame);
}
.ds-agent-card-actions {
  display: flex;
  align-items: center;
  gap: calc(var(--ds-space-control-gap, 0.5rem) / 2);
  margin-top: var(--ds-space-control-gap, 0.5rem);
}
.ds-agent-card-face--classic .ds-agent-card-art {
  top: 24%;
  left: var(--ds-space-control-inline, 0.75rem);
  right: var(--ds-space-control-inline, 0.75rem);
  bottom: 36%;
}

.ds-library-choice {display:block; width:220px; max-width:100%; padding:6px; border:0; border-radius:var(--ds-radius-card, 1rem); background:transparent; color:inherit; text-align:left; cursor:pointer; font-family:var(--ds-font-text, Inter, ui-sans-serif, system-ui, sans-serif);}
.ds-library-choice .ds-agent-card-face {display:block; box-sizing:border-box; height:auto; max-width:208px; margin:auto;}
.ds-agent-card-title {min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
.ds-agent-card-rules {display:block;}
.ds-agent-card-category,.ds-agent-card-rules {font-size:var(--ds-text-meta-size, 0.6875rem); line-height:var(--ds-text-meta-line, 1rem);}
.ds-agent-card-capability {display:block; font-weight:600;}
.ds-library-choice:hover .ds-agent-card-face {transform:translateY(-2px);}
.ds-library-choice[aria-pressed="true"] .ds-agent-card-face {outline:2px solid var(--ds-ring-focus, rgba(15,13,8,0.620)); outline-offset:5px;}
.ds-library-choice:focus-visible {outline:2px solid var(--ds-ring-focus, rgba(15,13,8,0.620)); outline-offset:2px;}
.ds-library-choice:disabled {pointer-events:none;}
@media(prefers-reduced-motion:reduce) {.ds-library-choice:hover .ds-agent-card-face {transform:none;}}
@media(forced-colors:active) {.ds-agent-card-face,.ds-agent-card-rules {border-color:CanvasText;}}
